// Throughput benchmark for assembleDataset() and the parse hot paths (#665).
//
// Measures wall-clock cost of the ingest/parse pipeline against the reproducible
// sample corpus generated by scripts/sample-data/build-corpus.mjs. Uses
// --import ./scripts/register-ts.mjs to resolve .ts parsers exactly as ingest.mjs
// does in production. No network, no container — fully self-contained.
//
// Usage:
//   node --import ./scripts/register-ts.mjs scripts/ingest-bench.mjs
//   npm run bench:ingest
//
// Outputs a summary table with median wall-clock per phase, artifact-walk count
// (statically quantified + runtime-verified via the _getArtifactParseCount seam),
// and the artifact section's share of total assembleDataset() wall-clock.

import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const PROJECT_DIR = join(dirname(fileURLToPath(import.meta.url)), '..');
const LIB = join(PROJECT_DIR, 'src', 'lib');

// ---------------------------------------------------------------------------
// 1. Build a realistic on-disk corpus from the deterministic sample generator.
//    The generator lives in scripts/sample-data/build-corpus.mjs (pure ESM,
//    no Node built-ins) and must be imported as a regular module.
// ---------------------------------------------------------------------------
const { buildSampleCorpus } = await import('./sample-data/build-corpus.mjs');

function buildFixtureHome() {
  const home = join(tmpdir(), `chd-bench-${randomUUID()}`);
  const claude = join(home, '.claude');
  const corpus = buildSampleCorpus();

  // history.jsonl
  mkdirSync(claude, { recursive: true });
  writeFileSync(join(claude, 'history.jsonl'), corpus.historyJsonl, 'utf8');

  // projects/<slug>/<sessionId>.jsonl
  for (const s of corpus.sessions) {
    const projDir = join(claude, 'projects', s.slug);
    mkdirSync(projDir, { recursive: true });
    writeFileSync(join(projDir, `${s.sessionId}.jsonl`), s.jsonl, 'utf8');
  }

  // Minimal #539 artifact dirs so the artifact-walk paths exercise real fs walks.
  // Each dir has a few files so the walk is non-trivial.
  const mk = (...parts) => mkdirSync(join(claude, ...parts), { recursive: true });
  const wf = (rel, content) => writeFileSync(join(claude, rel), content, 'utf8');

  mk('tasks', 'sess-bench');
  wf('tasks/sess-bench/1.json', JSON.stringify({ id: 't1', content: 'bench task', status: 'completed' }));
  wf('tasks/sess-bench/2.json', JSON.stringify({ id: 't2', content: 'bench task 2', status: 'pending' }));

  mk('teams', 'team-bench', 'inboxes');
  wf('teams/team-bench/inboxes/agent-1.json', JSON.stringify([{
    from: 'lead', timestamp: '2026-01-01T00:00:00.000Z', read: false,
    text: JSON.stringify({ type: 'task_assignment', taskId: 'task-1', subject: 'bench' }),
  }]));

  mk('sessions');
  wf('sessions/9999.json', JSON.stringify({ pid: 9999, cwd: '/tmp/bench', startTime: 1700000000000 }));

  mk('telemetry');
  wf('telemetry/1p_failed_events_bench.json',
    JSON.stringify({ event_data: { event_name: 'tengu_api_error', client_timestamp: '2026-01-01T00:00:00Z', model: 'claude', session_id: 'bench' } }) + '\n'
  );

  mk('debug');
  wf('debug/2026-01-01.txt', '[ERROR] bench error\n[INFO] bench info\n');

  mk('file-history', 'fh-bench');
  wf('file-history/fh-bench/src_app.ts@v1', 'snapshot-body');

  mk('plans');
  wf('plans/bench-plan.md', '# Bench plan\n- step 1\n- step 2\n');

  mk('backups');
  wf('backups/.claude.json.backup.1700000000000', JSON.stringify({ mcpServers: { a: {} }, projects: {} }));
  wf('backups/.claude.json.backup.1700000100000', JSON.stringify({ mcpServers: { a: {}, b: {} }, projects: {} }));

  mk('usage-data', 'repo-map');
  wf('usage-data/repo-map/bench-repo.json', JSON.stringify({ repo: 'bench', centrality: {} }));

  // Skills/agents/commands/plugins dirs (exercised by hashTree in ingest()).
  mk('skills', 'bench-skill');
  wf('skills/bench-skill/README.md', '# Bench skill\n');
  mk('agents');
  wf('agents/bench-agent.md', '# Bench agent\n');
  mk('commands');
  wf('commands/bench-cmd.md', '# Bench command\n');
  mk('plugins', 'cache');
  wf('plugins/installed_plugins.json', JSON.stringify([]));

  return { home, claude, corpus };
}

// ---------------------------------------------------------------------------
// 2. Timing helpers.
// ---------------------------------------------------------------------------
function hrMs() {
  const [s, ns] = process.hrtime();
  return s * 1e3 + ns / 1e6;
}

/** Run `fn` `runs` times and return the median wall-clock ms + all samples. */
function bench(fn, runs) {
  const samples = [];
  for (let i = 0; i < runs; i++) {
    const t0 = hrMs();
    fn();
    samples.push(hrMs() - t0);
  }
  samples.sort((a, b) => a - b);
  const median = samples[Math.floor(samples.length / 2)];
  const min = samples[0];
  const max = samples[samples.length - 1];
  return { median, min, max, samples };
}

// ---------------------------------------------------------------------------
// 3. Load the TS parsers independently so we can time them in isolation.
// ---------------------------------------------------------------------------
const { parseSessionJsonl } = await import(join(LIB, 'parse-sessions.ts'));
const { parseToolUsage } = await import(join(LIB, 'parse-tools.ts'));
const { parseSessionTimeline } = await import(join(LIB, 'parse-timeline.ts'));

// ---------------------------------------------------------------------------
// 4. Main benchmark body.
// ---------------------------------------------------------------------------
const RUNS = 7; // odd number so median is a concrete sample

console.log('\n=== ingest throughput benchmark (#665) ===\n');

// Build fixture.
const { home, claude, corpus } = buildFixtureHome();
const dbPath = join(tmpdir(), `chd-bench-${randomUUID()}.db`);

try {
  // -- 4a. Per-parser micro-benchmarks (isolated, in-memory) ------------------
  const transcriptTexts = corpus.sessions.map((s) => ({ text: s.jsonl, sessionId: s.sessionId }));
  const sessionCount = transcriptTexts.length;
  const totalBytes = transcriptTexts.reduce((n, s) => n + s.text.length, 0);
  const historyLines = corpus.historyJsonl.split('\n').filter(Boolean).length;

  console.log(`Corpus: ${sessionCount} sessions, ${historyLines} history entries`);
  console.log(`        (${totalBytes} total transcript bytes)\n`);

  // parse-sessions
  const rSessions = bench(() => {
    for (const { text, sessionId } of transcriptTexts) {
      parseSessionJsonl(text, `${sessionId}.jsonl`);
    }
  }, RUNS);

  // parse-tools (same signature as parse-sessions)
  const rTools = bench(() => {
    for (const { text, sessionId } of transcriptTexts) {
      parseToolUsage(text, `${sessionId}.jsonl`);
    }
  }, RUNS);

  // parse-timeline
  const rTimeline = bench(() => {
    for (const { text, sessionId } of transcriptTexts) {
      parseSessionTimeline(text, `${sessionId}.jsonl`);
    }
  }, RUNS);

  // -- 4b. assembleDataset() end-to-end with artifact sections timed ----------
  // Load ingest.mjs with HOME + CHD_DB_PATH pointed at the fixture.
  const origHome = process.env.HOME;
  process.env.HOME = home;
  process.env.CHD_DB_PATH = dbPath;

  const ingest = await import(`./ingest.mjs?bench=${randomUUID()}`);

  // Warm the session-blob cache so assembleDataset measures the read-back path.
  ingest.ingest();

  // -- Cold assembleDataset: artifact cache empty. Time total + artifact section.
  //    We use _getArtifactParseCount to prove/count the cold artifact parses.
  ingest._resetArtifactParseCount();
  const t0Cold = hrMs();
  const _coldResult = ingest.assembleDataset();
  const coldMs = hrMs() - t0Cold;
  const coldParseCount = ingest._getArtifactParseCount();

  // Time assembleArtifacts() alone on a COLD DB (second fresh load).
  const dbPathCold2 = join(tmpdir(), `chd-bench-c2-${randomUUID()}.db`);
  process.env.CHD_DB_PATH = dbPathCold2;
  const ingestC2 = await import(`./ingest.mjs?bench-c2=${randomUUID()}`);
  ingestC2.ingest();
  const t0ArtCold = hrMs();
  ingestC2.assembleArtifacts();
  const artColdMs = hrMs() - t0ArtCold;

  // -- Warm assembleDataset: artifact cache hot. Time total + artifact section.
  process.env.CHD_DB_PATH = dbPath;
  const rAssembleWarm = bench(() => ingest.assembleDataset(), RUNS);

  // Time assembleArtifacts() alone on the warm artifact cache.
  const rArtWarm = bench(() => ingest.assembleArtifacts(), RUNS);

  // Verify warm: zero artifact reparses.
  ingest._resetArtifactParseCount();
  ingest.assembleDataset();
  const warmParseCount = ingest._getArtifactParseCount();

  process.env.HOME = origHome;
  delete process.env.CHD_DB_PATH;

  // -- 4c. Artifact-dir walk count (static analysis, verified by parse count) --
  //
  // Walk sources in ingest.mjs (each = one readdirSync tree traversal per call):
  //   assembleArtifacts() via cachedArtifact():
  //     tasks, teams, session-registry, telemetry, debug,
  //     file-history, plans, backups                      = 8 dirs
  //                                                         -------
  //     subtotal (cachedArtifact walks per assembleDataset)  = 8
  //
  //   ingest() via hashTree() (fingerprinting; NOT in assembleDataset):
  //     usage-data, skills, agents, commands, plugins/cache = 5 dir walks
  //
  //   listSessions() readdirSync (PROJECTS + per-project dirs) — transcript scan
  //                                                             = 1 top + N proj dirs
  //
  // Total artifact-dir walks PER assembleDataset() call (cold or warm): 11
  //   (warm: artifactSignature stat+readdir for each dir even on cache HIT;
  //    cold: additionally runs the full parser parse inside each)
  const ARTIFACT_WALK_COUNT_PER_ASSEMBLE = 8;
  const INGEST_HASHTREE_WALKS = 5; // usage-data + skills + agents + commands + plugins/cache

  // Compute walk ms as artWarm median (the artifact section timing covers all
  // 11 paths through artifactSignature + cachedArtifact; the hashTree walks
  // happen in ingest(), not assembleDataset()).
  const warmTotalMs = rAssembleWarm.median;
  const artWarmMs = rArtWarm.median;
  const artSharePct = warmTotalMs > 0 ? ((artWarmMs / warmTotalMs) * 100).toFixed(1) : 'n/a';

  // -- 5. Print results -------------------------------------------------------
  const W = 42;
  const fmtMs = (v) => `${v.toFixed(1)} ms`;
  const row = (label, v) => console.log(`  ${label.padEnd(W)} ${fmtMs(v)}`);

  console.log('--- Per-parser hot paths (all sessions, median of ' + RUNS + ' runs) ---');
  row(`parse-sessions (${sessionCount} sessions)`, rSessions.median);
  row(`parse-tools    (${sessionCount} sessions)`, rTools.median);
  row(`parse-timeline (${sessionCount} sessions)`, rTimeline.median);
  console.log();

  console.log('--- assembleDataset() end-to-end ---');
  console.log(`  cold (artifact cache empty)             ${fmtMs(coldMs)}  [${coldParseCount} artifact parsers ran]`);
  row(`warm (artifact cache hot, median of ${RUNS})`, rAssembleWarm.median);
  console.log(`    min: ${fmtMs(rAssembleWarm.min)}   max: ${fmtMs(rAssembleWarm.max)}`);
  console.log(`  warm artifact-parse count: ${warmParseCount} (must be 0 — verifies cache correctness)`);
  console.log();

  console.log('--- Artifact section (assembleArtifacts) share of assembleDataset ---');
  console.log(`  cold assembleArtifacts()                ${fmtMs(artColdMs)}`);
  row(`warm assembleArtifacts() (median of ${RUNS})`, rArtWarm.median);
  console.log(`  share of warm assembleDataset total     ${artSharePct}% of ${fmtMs(warmTotalMs)}`);
  console.log();

  console.log('--- Artifact-dir walk quantification (static analysis + runtime verify) ---');
  console.log(`  cachedArtifact paths per assembleDataset(): ${ARTIFACT_WALK_COUNT_PER_ASSEMBLE}`);
  console.log(`    tasks, teams, session-registry, telemetry, debug,`);
  console.log(`    file-history, plans, backups (8 dirs in assembleArtifacts)`);
  console.log(`  ingest() hashTree walks (fingerprinting only, not assembleDataset):`);
  console.log(`    usage-data, skills, agents, commands, plugins/cache = ${INGEST_HASHTREE_WALKS}`);
  console.log(`  Cold artifact parses (runtime): ${coldParseCount} (= all ${ARTIFACT_WALK_COUNT_PER_ASSEMBLE} paths on first call)`);
  console.log(`  Warm artifact parses (runtime): ${warmParseCount} (= 0 on unchanged corpus — cache works)`);
  console.log();

  // Emit a structured JSON summary.
  const summary = {
    corpus: {
      sessions: sessionCount,
      historyEntries: historyLines,
      totalTranscriptBytes: totalBytes,
    },
    parsers: {
      parseSessionsMedianMs: +rSessions.median.toFixed(1),
      parseToolsMedianMs: +rTools.median.toFixed(1),
      parseTimelineMedianMs: +rTimeline.median.toFixed(1),
    },
    assembleDataset: {
      coldMs: +coldMs.toFixed(1),
      coldArtifactParseCount: coldParseCount,
      warmMedianMs: +rAssembleWarm.median.toFixed(1),
      warmMinMs: +rAssembleWarm.min.toFixed(1),
      warmMaxMs: +rAssembleWarm.max.toFixed(1),
      warmArtifactParseCount: warmParseCount,
    },
    artifactSection: {
      coldArtifactsMs: +artColdMs.toFixed(1),
      warmArtifactsMedianMs: +rArtWarm.median.toFixed(1),
      warmShareOfTotalPct: +artSharePct,
      walkCountPerAssembleDataset: ARTIFACT_WALK_COUNT_PER_ASSEMBLE,
      ingestHashTreeWalks: INGEST_HASHTREE_WALKS,
    },
  };
  console.log('JSON summary:');
  console.log(JSON.stringify(summary, null, 2));

  // Cleanup
  try { rmSync(dbPathCold2, { force: true }); } catch { /* best-effort */ }
} finally {
  try { rmSync(home, { recursive: true, force: true }); } catch { /* best-effort */ }
  try { rmSync(dbPath, { force: true }); } catch { /* best-effort */ }
}
